  function automatic logic is_cmdinfo_addr_4b(cmd_info_t ci, logic addr_4b_en);
    logic result;
    result = ci.addr_mode == AddrCfg ? addr_4b_en : (ci.addr_mode == Addr4B);
    return result;
  endfunction : is_cmdinfo_addr_4b

  // get_addr_mode removes AddrCfg.
