    CmdInfoEx4B         = CmdInfoEn4B + 1,
    CmdInfoWrEn         = CmdInfoEx4B + 1,
    CmdInfoWrDi         = CmdInfoWrEn + 1,
    NumTotalCmdInfo
  } cmd_info_index_e;

  parameter int unsigned NumReadCmdInfo = CmdInfoReadCmdEnd - CmdInfoReadCmdStart + 1;

  // NumCmdInfo adds two more entries (EN4B/ EX4B)
