  // Signal //
  ////////////
  sel_datapath_e sel_dp;
  assign sel_dp_o = sel_dp;
  `ASSERT_KNOWN(SelDpKnown_A, sel_dp_o)

  sel_datapath_e cmd_only_sel_dp;
  assign cmd_only_sel_dp_o = cmd_only_sel_dp;
  `ASSERT_KNOWN(CmdOnlySelDpKnown_A, cmd_only_sel_dp_o)

