    cmd_info_d = '{
      payload_dir: payload_dir_e'(PayloadIn),
      addr_mode: addr_mode_e'(0),
      read_pipeline_mode: read_pipeline_mode_e'(0),
      default: '0
    };
    cmd_info_idx_d = '0;
    if ((st == StIdle) && module_active && data_valid_i) begin
