                st_d = StStatus;
              end else if (cfg_intercept_en_status_i) begin
                st_d = StStatus;
                intercept_d = 1'b 1;
              end else begin
                st_d = StWait;
              end
            end

            opcode_readjedec: begin
              if (in_flashmode) begin
                st_d = StJedec;
              end else if (cfg_intercept_en_jedec_i) begin
                st_d = StJedec;
                intercept_d = 1'b 1;
              end else begin
                st_d = StWait;
              end
